-- ==================================================================
-- Migration 20: Complete policy pages (payment gateway website review)
-- Payment gateways such as Cashfree check a merchant's website before activating live payments: the
-- business name and registered address, Terms, Privacy, Refund, Cancellation and Shipping & Delivery
-- policies with clear timelines, and no placeholder text. This replaces the DRAFT policy texts from the
-- seed with complete ones (7-day refund window; admission and registration fees non-refundable; no
-- physical shipping), restores the Shipping & Delivery Policy page, sets the registered office address
-- (only when it is still empty) and refreshes the About intro and default meta description (only when
-- they still have the original seed text). Pages already edited in the admin (no longer marked DRAFT)
-- are left alone. The replaced texts stay in Admin -> Website -> Revision History.
-- Plain SQL that runs on MySQL 8 and MariaDB. Apply from admin -> Settings -> Database Updates.
-- ==================================================================
SET NAMES utf8mb4;

-- Keep the current draft texts in the revision history (restorable from the admin).
INSERT INTO cms_revisions (section_key, content, is_active)
SELECT section_key, content, is_active FROM cms_sections
WHERE section_key IN ('page_privacy', 'page_terms', 'page_refund', 'page_cancellation', 'page_delivery', 'page_disclaimer', 'page_cookies') AND JSON_UNQUOTE(JSON_EXTRACT(content, '$.intro')) LIKE 'DRAFT%';

UPDATE cms_sections SET content = '{"title":"Privacy Policy","intro":"This Privacy Policy explains how LAXYAM INNOVATIVE EDUSKIL PRIVATE LIMITED (\\"Laxyam Academy\\", \\"we\\", \\"us\\") collects, uses, shares and protects your personal information when you use laxyamacademy.com, take admission at our centres or buy a course. By using the website or our services you agree to this policy.","sections":[{"heading":"Who we are","body":"<p>Laxyam Academy is a brand of LAXYAM INNOVATIVE EDUSKIL PRIVATE LIMITED, a company incorporated in India (CIN U85491DL2026PTC470370) with its registered office at Shop in H.No. 22, Ground Floor, Badarpur, New Delhi - 110044. We run coaching classes for government job exams at our centres in New Delhi and give our students online access to lessons, notes and mock tests on laxyamacademy.com.</p>"},{"heading":"Information we collect","body":"<ul><li><strong>Account details:</strong> name, email address, mobile number and password (stored only in encrypted, hashed form).</li><li><strong>Admission and enquiry details:</strong> WhatsApp number, education qualification, the course you are interested in and any message you send us.</li><li><strong>Billing details:</strong> name, email, phone, state and, if you ask for a GST invoice, your GSTIN and billing address.</li><li><strong>Learning data:</strong> courses you join, lesson progress, test attempts and scores, doubts you ask and reviews you write.</li><li><strong>Payment information:</strong> order number, amount, payment status and the transaction reference sent to us by our payment gateway. We never see or store your card number, CVV, UPI PIN or net banking password.</li><li><strong>Technical data:</strong> IP address, browser and device type, and cookies (see our <a href=\\"/cookie-policy\\">Cookie Policy</a>).</li></ul>"},{"heading":"How we use your information","body":"<ul><li>To create and manage your account and give you access to the courses, classes and tests you enrol in.</li><li>To process enrolments and payments, issue invoices and handle refunds.</li><li>To send service messages such as login codes (OTP), payment receipts, class reminders, results and replies to your enquiries, by email, SMS or WhatsApp.</li><li>With your consent, to send you course updates, exam alerts and offers. You can opt out at any time.</li><li>To keep the website secure, prevent fraud and misuse, and improve our courses and services.</li><li>To meet our legal, tax and accounting obligations.</li></ul>"},{"heading":"Payments","body":"<p>Online payments on laxyamacademy.com are processed by our payment gateway partner, Cashfree Payments. You enter your card, UPI, net banking or wallet details on Cashfree''s secure payment page, not on our website. Cashfree handles that information under its own privacy policy and shares only the payment result and reference with us.</p>"},{"heading":"Sharing your information","body":"<p>We do not sell or rent your personal information. We share it only with:</p><ul><li>our payment gateway (Cashfree Payments) to process payments and refunds;</li><li>service providers who help us run the website and contact you, such as hosting, email, SMS and WhatsApp providers, under confidentiality obligations;</li><li>our faculty and staff, only as needed to teach you and support your admission;</li><li>government authorities, courts or law enforcement when the law requires it.</li></ul>"},{"heading":"How we protect it","body":"<p>The website uses HTTPS encryption. Passwords are stored as one-way hashes, payment card details never reach our servers, and access to student data is limited to authorised staff, with every admin action recorded in an audit log.</p>"},{"heading":"How long we keep it","body":"<p>We keep your account and learning data while your account is active. Invoices and payment records are kept for the period required by Indian tax and accounting laws. Other data is deleted or anonymised when it is no longer needed.</p>"},{"heading":"Your rights and choices","body":"<ul><li>View and update your profile and notification preferences from your dashboard.</li><li>Unsubscribe from promotional emails or messages at any time.</li><li>Download a copy of your data or ask for your account to be deleted from Settings in your dashboard, or write to <a href=\\"mailto:info@laxyamacademy.com\\">info@laxyamacademy.com</a> for any correction.</li><li>Withdraw consent you have given us, as provided under the Digital Personal Data Protection Act, 2023.</li></ul>"},{"heading":"Children","body":"<p>Our courses are for students preparing for competitive exams. Students under 18 should use the website and buy courses with the consent and supervision of a parent or guardian. Parents can contact us about their child''s data at any time.</p>"},{"heading":"Changes to this policy","body":"<p>We may update this policy from time to time. The \\"Last updated\\" date at the top of this page shows when it was last changed.</p>"},{"heading":"Grievance officer and contact","body":"<p>For any question or complaint about your personal information, contact our Grievance Officer. We acknowledge complaints within 2 working days and resolve them within 30 days.</p><p><strong>LAXYAM INNOVATIVE EDUSKIL PRIVATE LIMITED</strong> (brand: Laxyam Academy)<br>CIN: U85491DL2026PTC470370<br>Registered office: Shop in H.No. 22, Ground Floor, Badarpur, New Delhi - 110044<br>Email: <a href=\\"mailto:info@laxyamacademy.com\\">info@laxyamacademy.com</a><br>Phone / WhatsApp: <a href=\\"tel:+918700511018\\">+91 87005 11018</a></p>"}]}', is_active = 1
WHERE section_key = 'page_privacy' AND JSON_UNQUOTE(JSON_EXTRACT(content, '$.intro')) LIKE 'DRAFT%';

UPDATE cms_sections SET content = '{"title":"Terms & Conditions","intro":"These Terms & Conditions govern your use of laxyamacademy.com and of the courses, classes, mock tests and other services offered by LAXYAM INNOVATIVE EDUSKIL PRIVATE LIMITED under the brand Laxyam Academy. By creating an account, enrolling in a course or making a payment, you agree to these terms.","sections":[{"heading":"About us","body":"<p>Laxyam Academy is operated by LAXYAM INNOVATIVE EDUSKIL PRIVATE LIMITED (CIN U85491DL2026PTC470370), registered office Shop in H.No. 22, Ground Floor, Badarpur, New Delhi - 110044. We offer classroom (offline) coaching at our centres in New Delhi for government job exams such as SSC, Railway, Banking, Delhi Police and State government exams, foundation courses in Mathematics, Reasoning, GK/GS and English, and online access to lessons, notes and mock tests through the student dashboard.</p>"},{"heading":"Your account","body":"<ul><li>Give correct and complete details when you register or enrol.</li><li>Students under 18 may register and enrol only with the consent of a parent or guardian.</li><li>Keep your login details confidential. An account is for one student only and must not be shared.</li><li>We may suspend or close an account that is shared, misused or created with false information.</li></ul>"},{"heading":"Courses, fees and payment","body":"<ul><li>The course details, duration and fee of every course are shown on its course page in Indian Rupees (INR). Prices are inclusive of applicable taxes unless stated otherwise.</li><li>A sale price or offer applies only during the offer period shown on the course page.</li><li>You can pay online through our payment gateway, Cashfree Payments (UPI, debit and credit cards, net banking and wallets), or at our centre.</li><li>Your enrolment is confirmed when the payment is verified. An invoice is sent to your email and is available in your dashboard under My Purchases.</li><li>Other fees shown separately on a course page (for example admission, registration or ID card fees) apply only as stated there and as confirmed by our admissions desk.</li></ul>"},{"heading":"Course access and validity","body":"<p>Online access to an enrolled course starts in your dashboard as soon as the payment is verified and lasts for the access period shown on the course page. For classroom courses, our admissions team confirms the batch, timings and centre after you enrol. Batch timings, faculty or the classroom may change for academic reasons; we inform students in advance.</p>"},{"heading":"Classroom conduct","body":"<p>Students must follow the rules of the centre, carry their ID card, respect faculty, staff and other students, and must not disturb classes. We may suspend a student for serious misconduct.</p>"},{"heading":"Our content","body":"<p>All videos, notes, PDFs, tests and other material on the website and in our classes belong to Laxyam Academy or its licensors and are for your personal study only. You may not record, copy, download (unless a download is offered), share, resell or publish them. Doing so ends your access without a refund and may lead to legal action.</p>"},{"heading":"Mock tests, results and exam information","body":"<p>Mock tests, scores and ranks are for practice and are indicative only. Job and exam information on the website is a summary for convenience; the official notification of the recruiting body always prevails. Our courses support your preparation, but no course can guarantee selection, which depends on your own effort and the official selection process.</p>"},{"heading":"Refunds and cancellations","body":"<p>Refunds and cancellations are governed by our <a href=\\"/refund-policy\\">Refund Policy</a> and <a href=\\"/cancellation-policy\\">Cancellation Policy</a>. How and when services are delivered is described in our <a href=\\"/delivery-policy\\">Shipping &amp; Delivery Policy</a>.</p>"},{"heading":"Acceptable use","body":"<p>You must not misuse the website, for example by trying to hack it, by copying content with automated tools, by posting unlawful or abusive content in doubts or reviews, or by using someone else''s account or payment method.</p>"},{"heading":"Limitation of liability","body":"<p>We take care to keep the website and our services available and accurate, but we are not liable for indirect or consequential losses, or for interruptions caused by events outside our control. Our total liability for any claim about a course is limited to the fee you paid for that course.</p>"},{"heading":"Changes to these terms","body":"<p>We may update these terms from time to time. The updated terms apply from the date shown at the top of this page; continuing to use the website means you accept them.</p>"},{"heading":"Governing law and contact","body":"<p>These terms are governed by the laws of India, and the courts at New Delhi have exclusive jurisdiction. Before going to court, please contact us so that we can try to resolve your concern:</p><p><strong>LAXYAM INNOVATIVE EDUSKIL PRIVATE LIMITED</strong> (brand: Laxyam Academy)<br>CIN: U85491DL2026PTC470370<br>Registered office: Shop in H.No. 22, Ground Floor, Badarpur, New Delhi - 110044<br>Email: <a href=\\"mailto:info@laxyamacademy.com\\">info@laxyamacademy.com</a><br>Phone / WhatsApp: <a href=\\"tel:+918700511018\\">+91 87005 11018</a></p>"}]}', is_active = 1
WHERE section_key = 'page_terms' AND JSON_UNQUOTE(JSON_EXTRACT(content, '$.intro')) LIKE 'DRAFT%';

UPDATE cms_sections SET content = '{"title":"Refund Policy","intro":"This policy explains when fees paid to LAXYAM INNOVATIVE EDUSKIL PRIVATE LIMITED (Laxyam Academy) for a course are refunded, how to ask for a refund and how long it takes.","sections":[{"heading":"Refund window","body":"<p>You can ask for a refund within <strong>7 days of the payment date</strong>.</p>"},{"heading":"When a refund is given","body":"<p>A refund is approved when, on the day you ask for it, both of these are true:</p><ul><li>you have attended <strong>fewer than 2 classroom classes</strong> of the course, and</li><li>you have used <strong>less than 10% of the online content</strong> of the course (lessons, notes and mock tests).</li></ul><p>Requests made after 7 days, or after these limits have been crossed, are not eligible for a refund.</p>"},{"heading":"What is not refundable","body":"<ul><li>The admission fee and the registration fee.</li><li>The ID card fee and any other fee marked as non-refundable on the course page.</li><li>Courses whose access period has ended.</li></ul><p>When a discount, offer or coupon was applied, the refund is the amount you actually paid.</p>"},{"heading":"How to ask for a refund","body":"<p>Email <a href=\\"mailto:info@laxyamacademy.com\\">info@laxyamacademy.com</a> or call / WhatsApp <a href=\\"tel:+918700511018\\">+91 87005 11018</a> with your order number (for example LXA…), your registered email or mobile number and the reason, or visit our centre. We reply within 2 working days.</p>"},{"heading":"Refund processing time","body":"<p>An approved refund is initiated within <strong>5-7 working days</strong> to the original payment method (UPI, card, net banking or wallet) through our payment gateway, Cashfree Payments. Your bank may take a further 5-7 working days to show the amount in your account. Fees paid in cash at the centre are refunded by bank transfer.</p>"},{"heading":"Failed or duplicate payments","body":"<p>If money was debited but your enrolment was not confirmed, or you were charged twice for the same order, the extra amount is refunded in full. Most failed payments are reversed automatically by the bank; otherwise we refund them within 5-7 working days of your request.</p>"},{"heading":"If we cancel a course","body":"<p>If we cancel a course or batch before it starts, you get a full refund of all fees paid (including the admission and registration fee) or, if you prefer, a transfer to another batch.</p>"},{"heading":"After a refund","body":"<p>When a refund is made, your enrolment is cancelled and access to the course in your dashboard ends.</p>"}]}', is_active = 1
WHERE section_key = 'page_refund' AND JSON_UNQUOTE(JSON_EXTRACT(content, '$.intro')) LIKE 'DRAFT%';

UPDATE cms_sections SET content = '{"title":"Cancellation Policy","intro":"This policy explains how you can cancel an enrolment with LAXYAM INNOVATIVE EDUSKIL PRIVATE LIMITED (Laxyam Academy), and what happens when we cancel or reschedule a class or batch.","sections":[{"heading":"Cancelling your enrolment","body":"<p>You can cancel your enrolment within 7 days of the payment date by writing to <a href=\\"mailto:info@laxyamacademy.com\\">info@laxyamacademy.com</a>, calling / WhatsApp <a href=\\"tel:+918700511018\\">+91 87005 11018</a>, or visiting our centre with your order number. If the conditions of our <a href=\\"/refund-policy\\">Refund Policy</a> are met, your fee is refunded as described there. After 7 days you may stop attending at any time, but the fee is not refunded.</p>"},{"heading":"Unpaid or failed orders","body":"<p>An order that is not paid, or whose payment fails, is cancelled automatically and nothing is charged. If money was debited for a failed payment, it is refunded as described in the Refund Policy.</p>"},{"heading":"Changing your batch","body":"<p>A change to another batch of the same course may be allowed on request, depending on seat availability. Ask our admissions desk.</p>"},{"heading":"Classes cancelled or rescheduled by us","body":"<p>If a class has to be cancelled, it is rescheduled and students are informed on the website, by SMS or on WhatsApp. For online live classes a recording or a rescheduled class is provided.</p>"},{"heading":"Course or batch cancelled by us","body":"<p>If we cancel a course or batch before it starts, you can choose a full refund of all fees paid or a transfer to another batch.</p>"},{"heading":"Cancellation for misuse","body":"<p>We may cancel the enrolment of a student who shares their account, copies or distributes our content, or seriously breaks the centre rules. No refund is given in these cases.</p>"}]}', is_active = 1
WHERE section_key = 'page_cancellation' AND JSON_UNQUOTE(JSON_EXTRACT(content, '$.intro')) LIKE 'DRAFT%';

UPDATE cms_sections SET content = '{"title":"Shipping & Delivery Policy","intro":"Laxyam Academy (LAXYAM INNOVATIVE EDUSKIL PRIVATE LIMITED) provides education services: classroom coaching at our centres in New Delhi and online learning on laxyamacademy.com. We do not sell or ship physical products. This policy explains how and when the services you pay for are delivered.","sections":[{"heading":"No physical shipping","body":"<p>We do not courier books, notes or any other goods. Any printed study material included in a classroom course is handed over to students at our centre. Online lessons, notes and mock tests are delivered in your student dashboard.</p>"},{"heading":"Online access","body":"<p>As soon as your payment is verified, the course appears in <strong>My Courses</strong> in your dashboard, usually within a few minutes. You also receive a confirmation email and your invoice.</p>"},{"heading":"Classroom courses","body":"<p>After you enrol, our admissions team contacts you within 1 working day to confirm your batch, class timings and centre. Classes are held at our centres:</p><ul><li>Badarpur: Shop in H.No. 22, Ground Floor, Badarpur, New Delhi - 110044</li><li>West Sagarpur: RZ 6C/322, Street No. 8/9, Madanpuri, West Sagarpur, South West Delhi - 110046</li></ul><p>Classes start on the batch start date shared with you.</p>"},{"heading":"Delivery timelines","body":"<ul><li><strong>Online course access:</strong> immediately after payment verification (at the latest within 24 hours).</li><li><strong>Classroom course:</strong> batch confirmation within 1 working day; classes from the batch start date.</li><li><strong>Invoice:</strong> emailed at once and always available under My Purchases.</li></ul>"},{"heading":"Service area","body":"<p>Online access is available anywhere in India with an internet connection. Classroom courses are delivered at our New Delhi centres.</p>"},{"heading":"If you have not received access","body":"<p>If your course does not appear in your dashboard within 24 hours of a successful payment, contact us at <a href=\\"mailto:info@laxyamacademy.com\\">info@laxyamacademy.com</a> or <a href=\\"tel:+918700511018\\">+91 87005 11018</a> with your order number. We activate your access at once or, if we cannot, refund the full amount.</p>"}]}', is_active = 1, title = 'Shipping & Delivery Policy'
WHERE section_key = 'page_delivery' AND JSON_UNQUOTE(JSON_EXTRACT(content, '$.intro')) LIKE 'DRAFT%';

UPDATE cms_sections SET content = '{"title":"Disclaimer","intro":"General information about the content of laxyamacademy.com, operated by LAXYAM INNOVATIVE EDUSKIL PRIVATE LIMITED under the brand Laxyam Academy.","sections":[{"heading":"Not a government website","body":"<p>Laxyam Academy is a private coaching institute. It is not affiliated with or endorsed by SSC, RRB, IBPS, SBI, Delhi Police, UPSC, any State Public Service Commission or any other government or recruiting body.</p>"},{"heading":"Job and exam notifications","body":"<p>Job alerts and exam information on this website are summaries for convenience. Always read the official notification on the recruiting body''s website before applying; the official notification prevails.</p>"},{"heading":"No guarantee of selection","body":"<p>Our courses, classes and mock tests support your preparation. Results depend on individual effort and the official selection process, and no course guarantees selection.</p>"},{"heading":"Accuracy of information","body":"<p>We try to keep course details, fees and schedules up to date. If something on the website is wrong, the details confirmed by our admissions desk apply, and we correct the website as soon as possible.</p>"},{"heading":"External links","body":"<p>Links to external websites are provided for information. We are not responsible for their content or policies.</p>"}]}', is_active = 1
WHERE section_key = 'page_disclaimer' AND JSON_UNQUOTE(JSON_EXTRACT(content, '$.intro')) LIKE 'DRAFT%';

UPDATE cms_sections SET content = '{"title":"Cookie Policy","intro":"This policy explains which cookies and similar technologies laxyamacademy.com uses and how you can control them.","sections":[{"heading":"Essential cookies","body":"<p>We use an essential session cookie to keep you signed in and to protect forms from misuse. It is deleted when you log out or close your browser. The website cannot work without it.</p>"},{"heading":"Preferences","body":"<p>Your browser may store small settings, such as a chosen language or dismissed pop-ups, so that the website remembers them on your next visit.</p>"},{"heading":"Security","body":"<p>Our forms may use Google reCAPTCHA to stop spam and automated abuse. Google may set its own cookies for this purpose.</p>"},{"heading":"Analytics and marketing","body":"<p>When analytics is switched on, tools such as Google Analytics measure how visitors use the website, for example which pages are visited. These tools may set their own cookies. We do not sell any information collected through cookies.</p>"},{"heading":"Payments","body":"<p>During checkout our payment gateway partner, Cashfree Payments, may set its own cookies to process your payment securely.</p>"},{"heading":"Controlling cookies","body":"<p>You can block or delete cookies in your browser settings. If you block the essential cookie, you will not be able to sign in or buy a course.</p>"}]}', is_active = 1
WHERE section_key = 'page_cookies' AND JSON_UNQUOTE(JSON_EXTRACT(content, '$.intro')) LIKE 'DRAFT%';

-- About page intro: current courses and the company behind the brand (only the untouched seed text).
UPDATE cms_sections SET content = JSON_SET(content, '$.intro', 'Laxyam Academy is a coaching institute for government job exams, run by LAXYAM INNOVATIVE EDUSKIL PRIVATE LIMITED from its centres in Badarpur and West Sagarpur, New Delhi. We prepare students for SSC, Railway, Banking, Delhi Police and State government exams with classroom courses, foundation courses in Mathematics, Reasoning, GK/GS and English, regular mock tests and study material in the student dashboard.')
WHERE section_key = 'page_about' AND JSON_UNQUOTE(JSON_EXTRACT(content, '$.intro')) = 'Laxyam Academy is a competitive exam preparation institute based in Badarpur, New Delhi. We help aspirants prepare for UPSC, SSC, Banking, State PSC, Railway, Defence, Teaching and Police examinations through structured courses, live and recorded classes, mock tests and study material.';

-- Registered office address (Contact page, policies, invoices, email footer) - only when still empty.
INSERT INTO site_settings (setting_key, setting_value, setting_group, is_public)
VALUES ('company_registered_address', 'Shop in H.No. 22, Ground Floor, Badarpur, New Delhi - 110044', 'company', 1)
ON DUPLICATE KEY UPDATE setting_value = IF(setting_value IS NULL OR TRIM(setting_value) = '', VALUES(setting_value), setting_value);

-- Default meta description without the exams the academy no longer teaches (only the untouched seed text).
UPDATE site_settings SET setting_value = 'Classroom coaching for government job exams in New Delhi - SSC, Railway, Banking, Delhi Police and State exams - with foundation courses, mock tests and study material from Laxyam Academy.'
WHERE setting_key = 'default_seo_description' AND setting_value = 'Prepare for UPSC, SSC, Banking, State PSC, Railway, Defence, Teaching and Police exams with structured courses, live classes, mock tests and study material from Laxyam Academy, New Delhi.';

INSERT INTO schema_migrations (version, description) VALUES (20, 'Complete policy pages for the payment gateway review');
